"""Export the actual bounded A8C1/9B85/9C6D static reads, including actor-index aliases."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
rom=(ROOT/'.local/nes-basket/basketball.nes').read_bytes();digest=hashlib.sha256(rom).hexdigest();assert digest=='0fa28f60abb8d2ccbbeee90e79e3fa160a5cf32feb90f47ebf1a89168cff569b'
bank=rom[16+5*16384:16+6*16384];read=lambda a:bank[a-0x8000];word=lambda a:read(a)+256*read(a+1)
selectors=[[0 if holder==6 else read(0x9c8b+actor*4+holder) for holder in range(7)] for actor in range(4)]
plans=[[[read(word(0x9467+profile*2)+selectors[actor][holder]) for holder in range(7)] for actor in range(4)] for profile in range(6)]
lines=['// Code generated by scripts/basketball/export_ai_resume_plans.py; DO NOT EDIT.','package engine','','// A8C1 retains X=actor in 9C6D. These are its actual static return values,','// including adjacent bytes; do not substitute the separate team-role table.','var originalCommandResumePlans = [6][4][7]uint8{']
for profile in plans:lines.append('{'+','.join('{'+','.join(str(v) for v in actor)+'}' for actor in profile)+'},')
lines.append('}');(ROOT/'games/basketball/engine/ai_command_resume_profiles.go').write_text('\n'.join(lines)+'\n')
(ROOT/'games/basketball/engine/testdata/ai-command-resume-table-source.json').write_text(json.dumps(dict(rom_sha256=digest,source_is_static_data=True,selectors=selectors,profile_pointers=[word(0x9467+i*2) for i in range(6)],actual_return_modes=plans),indent=2)+'\n')
